import { ws } from "msw";

export type RealtimeConnection = {
  readonly url: string;
  readonly receivedFrames: readonly unknown[];
  readonly closed: boolean;
  push: (message: unknown) => void;
  pushRaw: (data: string) => void;
  failWithNetworkError: () => void;
  drop: () => void;
};

export const createFakeRealtime = (options: { available: boolean }) => {
  let available = options.available;
  const connectionAttempts: string[] = [];
  const connections: RealtimeConnection[] = [];

  const handler = ws.link("*").addEventListener("connection", ({ client }) => {
    connectionAttempts.push(client.url.href);
    if (!available) {
      client.close();
      return;
    }

    const receivedFrames: unknown[] = [];
    let closed = false;
    client.addEventListener("message", (event) => {
      receivedFrames.push(JSON.parse(String(event.data)));
    });
    client.addEventListener("close", () => {
      closed = true;
    });

    connections.push({
      url: client.url.href,
      receivedFrames,
      get closed() {
        return closed;
      },
      push: (message) => client.send(JSON.stringify(message)),
      pushRaw: (data) => client.send(data),
      failWithNetworkError: () => client.socket.dispatchEvent(new Event("error")),
      drop: () => client.close(),
    });
  });

  return {
    handler,
    connectionAttempts,
    connections,
    makeAvailable: () => {
      available = true;
    },
    makeUnavailable: () => {
      available = false;
    },
  };
};
EOF
